T["All: Never stand in front of or behind Onyxia (breath/tail).\nPhase 2 from 65%: dodge fireballs, kill whelps at once.\nPhase 3 from 40%: fear - grounding totem and fear ward ready.\nTank: Onyxia with her back to the wall, head away from the raid.\nTank: phase 3 take aggro back at once.\nHealer: tank first, spread out in phase 2.\nDPS: go full only after 3 sunders from the tank.\nDPS: phase 2: whelps before Onyxia."] = "Tous : ne jamais se placer devant ou derrière Onyxia (souffle/queue).\nPhase 2 dès 65% : esquiver les boules de feu, tuer les dragonnets aussitôt.\nPhase 3 dès 40% : peur - totem de glèbe et gardien de peur prêts.\nTank : Onyxia dos au mur, tête loin du raid.\nTank : phase 3, reprendre l'aggro aussitôt.\nSoigneur : priorité au tank, se disperser en phase 2.\nDPS : à fond seulement après 3 Fracasser armure du tank.\nDPS : phase 2 : dragonnets avant Onyxia."
T["All: swarm target: run out.\nTank: infernal tank off to the side.\nHealer: remove sleep where possible.\nDPS: ignore infernals, everything on the boss."] = "Tous : cible de l'essaim : sortir.\nTank : tank des infernaux à l'écart.\nSoigneur : dissiper le sommeil si possible.\nDPS : ignorer les infernaux, tout sur le boss."
T["All: leave Death and Decay at once.\nTank: hold the middle, don't move during frost nova.\nHealer: heal the ice block target fast.\nDPS: ranged spread wide (icebolt chain)."] = "Tous : quitter Mort et pourriture aussitôt.\nTank : tenir le centre, ne pas bouger pendant Nova de givre.\nSoigneur : soigner vite la cible du bloc de glace.\nDPS : distance bien dispersée (chaîne d'Éclair de givre)."
