T["Automatic: every 10 minutes and on logout Oasis stores a snapshot in the saved variables (WTF/Account/<account>/SavedVariables/Oasis.lua). The program Tools/oasis_export.py reads the file, turns it into JSON and can send it to your web page. Addons have no internet access - this is the safe way."] = "Automatique : toutes les 10 minutes et à la déconnexion, Oasis enregistre un instantané dans les variables sauvegardées (WTF/Account/<compte>/SavedVariables/Oasis.lua). Le programme Tools/oasis_export.py lit le fichier, le convertit en JSON et peut l'envoyer à votre page web. Les addons n'ont pas accès à Internet - c'est la voie sûre."
