T["You'll find the download in our Discord."] = "Le téléchargement se trouve sur notre Discord."
T["You can also drag the button around the minimap."] = "Tu peux aussi déplacer le bouton autour de la minicarte avec la souris."
T["The raid simulator is only available in the developer version."] = "Le simulateur de raid n'existe que dans la version de développement."
T["Only leadership, raid leaders and raid assistants may edit the raid plan."] = "Seuls la direction, les chefs de raid et les assistants de raid peuvent modifier le plan de raid."
T["WoW can't show this class's talent tree here. You can copy the export string below."] = "WoW ne peut pas afficher ici l'arbre de talents de cette classe. Le texte d'export peut être copié ci-dessous."
T["Delete the whole history with %s? Saved messages are deleted too."] = "Supprimer tout l'historique avec %s ? Les messages mémorisés partent aussi."
T["The order goes to every crafter with this recipe - whoever has time takes it."] = "La commande va à tous les artisans ayant cette recette - qui a le temps la prend."
T["The order is withdrawn for everyone."] = "La commande est retirée pour tout le monde."
T["The customer is told it's ready."] = "Le demandeur est prévenu que c'est prêt."
T["The requester will be notified."] = "Le demandeur sera prévenu."
T["The bazaar is empty"] = "Le bazar est vide"
T["The Barrens chat with its sayings"] = "Le chat des Tarides et ses répliques"
T["The client delivers no skills right now - wait a moment after logging in."] = "Le client ne fournit pas de compétences pour l'instant - patiente un peu après la connexion."
T["The dungeon compass: which dungeon fits, what drops there for you."] = "La boussole des donjons : quel donjon convient, ce qui y tombe pour toi."
T["The enemy was not in front of you. It was behind you. The whole time."] = "L'ennemi n'était pas devant toi. Il était derrière toi. Tout ce temps."
T["The group leader can make you an assistant."] = "Le chef de groupe peut te nommer assistant."
T["The fight was locked at first and was recorded afterwards."] = "Le combat était d'abord verrouillé et a été analysé après coup."
T["The button can no longer be dragged"] = "Le bouton ne peut plus être déplacé à la souris"
T["The link applies to all officers."] = "Le lien vaut pour toute la direction."
T["The market uses prices from the AH addon Midas. As soon as you or a guild member scans the AH with Midas, this page unlocks."] = "Le marché utilise les prix de l'addon d'HV Midas. Dès que toi ou un membre de la guilde scannez l'hôtel des ventes avec Midas, cette page se débloque."
T["Play-time tracking is off. Turn it on and Oasis learns a little more every evening."] = "L'enregistrement des temps de jeu est désactivé. Active-le et Oasis en apprend un peu plus chaque soir."
T["The Oasis rank is Oasis's guild rank - it rises by playing together, helping, crafting, events and badges."] = "Le rang Oasis est le rang de guilde d'Oasis - il monte en jouant ensemble, en aidant, par l'artisanat, les événements et les badges."
T["This person's online sound is muted for you."] = "Le son de connexion de cette personne est coupé chez toi."
T["The Oasis window border glows in your colour"] = "La bordure de la fenêtre Oasis brille de ta couleur"
T["The ring shows who has nothing open."] = "L'anneau montre qui n'a plus rien en attente."
T["The Stone Eater"] = "Le Mange-pierre"
T["That date is in the past."] = "L'événement est dans le passé."
T["Details"] = "Détails"
T["Tue"] = "Mar"
T["Diagnostics and sync"] = "Diagnostic et synchronisation"
T["Diamond"] = "Diamant"
T["Diamond = Banish (Warlock)"] = "Diamant = Bannir (Démoniste)"
T["Visited the bank. Just counting real quick."] = "Visite à la banque. Recompter vite fait."
T["The ban list is empty."] = "La liste des bannis est vide."
T["The chat input was touched by Oasis (e.g. 'Whisper' button), then /target was typed."] = "La saisie du chat a été touchée par Oasis (ex. bouton « Chuchoter »), puis /target a été saisi."
T["The chat input was touched by Oasis (e.g. 'Whisper' button), then a /cast command was typed there."] = "La saisie du chat a été touchée par Oasis (ex. bouton « Chuchoter »), puis une commande /cast y a été saisie."
T["The chat input was touched by Oasis, then /focus was typed."] = "La saisie du chat a été touchée par Oasis, puis /focus a été saisi."
T["The chat input was touched by Oasis, then a spell command was typed."] = "La saisie du chat a été touchée par Oasis, puis une commande de sort a été saisie."
T["Dungeon maps have no coordinates. Click here, then on the spot where you stand. Done at two distant spots, Oasis shows you and your group on the map - for the whole guild."] = "Les cartes de donjon n'ont pas de coordonnées. Clique ici, puis sur l'endroit de la carte où tu te trouves. Fait à deux endroits éloignés, Oasis te montre avec ton groupe sur la carte - pour toute la guilde."
T["The guild will be notified"] = "La guilde est prévenue"
T["The guild can see whom you react to. Default: off"] = "La guilde voit à qui tu réponds. Par défaut : désactivé"
T["The guild sees your fire on the map for %d minutes."] = "La guilde voit ton feu sur la carte pendant %d minutes."
T["The guild sees your achievements in the chronicle"] = "La guilde voit dans la chronique ce que tu as accompli"
T["The guild isn't looking for anything from this dungeon."] = "La guilde ne cherche rien dans ce donjon pour l'instant."
T["Your guild doesn't award loot points yet - your values appear once the raid leaders start a raid."] = "La guilde n'attribue pas encore de points de butin - tes valeurs apparaissent dès que la direction de raid lance un raid."
T["The guild bank hasn't been read yet"] = "La banque de guilde n'a pas encore été lue"
T["The guild leadership names raid leaders and assistants under Crown > Modules > Raids & Loot (by name or from a guild rank). In a running raid, the raid leader and assistants count too."] = "La direction de la guilde nomme chefs de raid et assistants sous Couronne > Modules > Raids & butin (par nom ou à partir d'un rang de guilde). Dans un raid en cours, le chef de raid et les assistants comptent aussi."
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader and assistants count too."] = "La direction de la guilde nomme les chefs de raid sous Couronne > Modules > Raids & butin. Dans un raid en cours, le chef de raid et les assistants comptent aussi."
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "La direction de la guilde nomme les chefs de raid sous Couronne > Modules > Raids & butin. Dans un raid en cours, le chef de raid compte aussi."
T["The guild leadership only allows group searches from a higher rank."] = "La direction de la guilde n'autorise les recherches de groupe qu'à partir d'un rang plus élevé."
T["The guild leadership only allows polls from a higher rank."] = "La direction de la guilde n'autorise les sondages qu'à partir d'un rang plus élevé."
T["The guild leadership has disabled the partner search."] = "La direction de la guilde a désactivé la recherche de partenaires."
T["The guild leadership has disabled open invites - challenge someone directly."] = "La direction de la guilde a désactivé les invitations ouvertes - défie quelqu'un directement."
T["The guild leadership sets which ranks may do this under Crown > Modules."] = "La direction de la guilde définit sous Couronne > Modules quels rangs y ont droit."
T["WoW's guild finder helps - neutral, no ads."] = "L'outil de recherche de guilde de WoW aide à trouver - neutre, sans publicité."
T["Only the guild master sets the limit. Rank 1 = guild master."] = "Seul le maître de guilde fixe la limite. Rang 1 = maître de guilde."
T["The buttons put the command into the chat line - it only runs when you press Enter."] = "Les boutons écrivent la commande dans la ligne de chat - elle ne s'exécute qu'avec Entrée."
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window (not in combat - there Esc belongs to the game)."] = "Les raccourcis figurent aussi dans les raccourcis clavier de WoW sous AddOns > Oasis. Échap ferme la fenêtre Oasis (pas en combat - là, Échap appartient au jeu)."
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window as long as you last clicked into it."] = "Les raccourcis figurent aussi dans les raccourcis clavier de WoW sous AddOns > Oasis. Échap ferme la fenêtre Oasis tant que tu as cliqué dedans en dernier."
T["The bar rolls up out of view; move the mouse to the top edge and it comes down (only when docked at the top)"] = "La barre se replie vers le haut ; amène la souris au bord supérieur et elle redescend (seulement si elle est ancrée en haut)"
T["The reservation line only appears while you are in a group or raid"] = "La ligne de réservation n'apparaît que si tu es en groupe ou en raid"
T["The Scale of the Sands"] = "La Balance des sables"
T["Opened the world map. Where was north again?"] = "Carte du monde ouverte. Où était le nord déjà ?"
T["The real bar above shows every change instantly"] = "La vraie barre en haut montre chaque changement aussitôt"
T["The first 20 stamina give 1 health each, every further point 10."] = "Les 20 premiers points d'Endurance donnent 1 chacun, chaque point suivant 10 points de vie."
T["Most ghost runs in the guild. The graveyard has a bench with your name on it."] = "Le plus de courses de fantôme de la guilde. Le cimetière a un banc à ton nom."
