T["Who sends data that others reject (no permission, forged author, made-up entries). An unmodified Oasis practically never does this - a hint, not proof."] = "Ceux qui envoient des données refusées chez les autres (pas de droits, auteur falsifié, entrées inventées). Un Oasis non modifié ne le fait quasiment jamais - un indice, pas une preuve."
T["Anyone who registers interest appears in a matching slot. Once there is an event, sign up directly on its card."] = "Ceux qui signalent leur intérêt apparaissent ici sur un créneau adapté. Une fois l'événement fixé, inscrivez-vous directement sur sa carte."
T["Who in the guild has the item on their wishlist"] = "Qui dans la guilde a l'objet sur sa liste de souhaits"
