T["Whoever shows up often and has received little gets first pick on 'Need'. Part of the points decays every week."] = "Ceux souvent présents qui ont peu reçu passent en premier en 'Besoin'. Une partie des points décroît chaque semaine."
T["Anyone who signs up with a fitting role is invited to your group right away."] = "Ceux qui s'inscrivent avec un rôle adapté sont invités immédiatement dans votre groupe."
