T["Stats"] = "Stats"
T["stats do nothing for your role"] = "stats inutiles pour votre rôle"
T["stats for info only"] = "stats à titre indicatif"
T["Stats, yearbook, daily goal, records and adventures of your character."] = "Stats, annuaire, objectif du jour, records et aventures de votre personnage."
T["Stats: +healing, intellect, spirit, mp5;Weapon: staff or one-hander + off-hand with healing;Healing: Rejuvenation and Regrowth ahead, Healing Touch for big hits;Tip: Innervate for mana, Rebirth for fallen healers"] = "Stats : +soins, intelligence, esprit, régén. mana;Arme : bâton ou arme à une main + main gauche avec soins;Soins : Récupération et Rétablissement en avance, Toucher guérisseur pour les gros coups;Astuce : Innervation pour le mana, Renaissance pour les soigneurs tombés"
T["Stats: +healing, intellect, spell crit (Illumination refunds mana), mp5;Weapon: one-hander + off-hand/shield with healing;Healing: Flash of Light for small damage, Holy Light (low rank) for big hits;Tip: hand out blessings, Divine Protection when you pull aggro"] = "Stats : +soins, intelligence, critique des sorts (Illumination rend du mana), régén. mana;Arme : arme à une main + main gauche/bouclier avec soins;Soins : Éclair lumineux pour les petits dégâts, Lumière sacrée (rang bas) pour les gros coups;Astuce : distribuer les bénédictions, Protection divine si vous prenez l'aggro"
T["Stats: +healing, mp5, intellect - spirit does little;Weapon: one-hander + shield with healing;Healing: Chain Heal for groups, Healing Wave (low rank) for the tank;Tip: drop Mana Spring Totem, Earth Shield on the tank"] = "Stats : +soins, régén. mana (MP5), intelligence - l'esprit apporte peu;Arme : arme à une main + bouclier avec soins;Soins : Salve de guérison pour les groupes, Vague de soins (rang bas) pour le tank;Astuce : poser le Totem Fontaine de mana, Bouclier de terre sur le tank"
T["Stats: +healing, spirit (Meditation: regen while casting), intellect, mp5;Weapon: staff or one-hander + off-hand with healing, wand;Healing: Renew and Power Word: Shield ahead, Greater Heal (low rank) for the tank;Tip: Prayer of Healing for the group, Fade on aggro"] = "Stats : +soins, esprit (Méditation : régén. même en incantant), intelligence, régén. mana;Arme : bâton ou arme à une main + main gauche avec soins, baguette;Soins : Rénovation et Mot de pouvoir : Bouclier en avance, Soins supérieurs (rang bas) pour le tank;Astuce : Prière de soins pour le groupe, Oubli en cas d'aggro"
T["Stats: armor (bear form multiplies it), stamina, agility (dodge + armor);Weapon: damage doesn't matter - only the stats (staff/polearm with stamina);Rotation: Maul, Swipe for packs, Demoralizing Roar;Tip: strength for more threat, Enrage to start"] = "Stats : armure (la forme d'ours la multiplie), endurance, agilité (esquive + armure);Arme : peu importe pour les dégâts - seules les stats comptent (bâton/arme d'hast avec endurance);Rotation : Mutilation, Balayage pour les groupes, Rugissement démoralisant;Astuce : force pour plus de menace, Enrager au début"
T["Stats: strength (1 point = 2 AP), agility (AP + crit), crit, hit up to +9 %;Weapon: damage doesn't matter - only the stats;Rotation: Claw/Shred for combo points, then Ferocious Bite;Tip: powershift (recast form) for energy, open from stealth"] = "Stats : force (1 point = 2 PA), agilité (PA + crit), crit, toucher jusqu'à +9 %;Arme : peu importe pour les dégâts - seules les stats comptent;Rotation : Griffe/Lambeau pour les points de combo, puis Morsure féroce;Astuce : changer de forme pour l'énergie, bondir depuis le rôdeur"
T["Stats: strength (1 point = 2 AP), crit (procs Flurry = faster swings), hit up to +9 %;Weapon: slow two-hander - Windfury procs per swing, so slower = more damage;Rotation: Windfury Weapon, Stormstrike, Earth Shock;Tip: Strength of Earth and Windfury Totem for the group"] = "Stats : force (1 point = 2 PA), crit (déclenche Rafale = frappes plus rapides), toucher jusqu'à +9 %;Arme : arme à deux mains lente - Furie-des-vents frappe par coup, donc plus lente = plus de dégâts;Rotation : Arme Furie-des-vents, Frappe-tempête, Horion de terre;Astuce : Totem de Force de la Terre et Totem Furie-des-vents pour le groupe"
T["Stats: strength (1 point = 2 AP), crit, hit up to +9 %;Weapon: slow two-hander - seals and Judgement scale per swing;Rotation: Seal of Righteousness/Command, Judgement, reapply seal;Tip: Consecration only with enough mana, Blessing of Might on yourself"] = "Stats : force (1 point = 2 PA), crit, toucher jusqu'à +9 %;Arme : arme à deux mains lente - sceaux et Jugement agissent par coup;Rotation : Sceau de piété/d'autorité, Jugement, reposer le sceau;Astuce : Consécration seulement avec assez de mana, Bénédiction de puissance sur vous"
T["Stats: hit up to +9 %, agility (1 AP, ~29 = 1 % crit), AP, crit;Weapon: Combat = fast off-hand, slow main hand (Sinister Strike); daggers for Backstab;Rotation: build combo points, keep Slice and Dice up, then Eviscerate;Tip: dual wielding misses white hits more often - hit matters most"] = "Stats : toucher jusqu'à +9 %, agilité (1 PA, env. 29 = 1 % crit), PA, crit;Arme : Combat = main gauche rapide, main droite lente (Attaque pernicieuse) ; dagues pour Embuscade;Rotation : accumuler des points de combo, maintenir Débiter, puis Éviscération;Astuce : avec deux armes, les coups normaux ratent plus souvent - le toucher est le plus important"
T["Stats: hit up to +9 %, agility (2 ranged AP, ~53 = 1 % crit), AP, intellect;Weapon: slow ranged weapon (big damage per shot), melee weapon for stats;Rotation: Hunter's Mark, Auto Shot, Aimed Shot/Multi-Shot in between;Tip: feed your pet and keep it happy, Freezing Trap (square) for control"] = "Stats : toucher jusqu'à +9 %, agilité (2 PA distance, env. 53 = 1 % crit), PA, intelligence;Arme : arme à distance lente (gros dégâts par tir), arme de mêlée avec stats;Rotation : Marque du chasseur, Tir automatique, Visée/Flèches multiples entre deux;Astuce : nourrir le familier et le garder heureux, Piège givrant (carré) pour le contrôle"
T["Stats: hit up to +9 %, strength (1 point = 2 AP), crit (~20 agility = 1 %);Weapon: slow two-hander (Mortal Strike, Heroic Strike scale per swing);Rotation: build rage, Mortal Strike / Bloodthirst, Whirlwind, spare rage into Heroic Strike;Tip: Battle Shout before the pull, Execute below 20 % health"] = "Stats : toucher jusqu'à +9 %, force (1 point = 2 PA), crit (env. 20 agilité = 1 %);Arme : arme à deux mains lente (Frappe mortelle, Frappe héroïque agissent par coup);Rotation : générer de la rage, Frappe mortelle / Sanguinaire, Tourbillon, rage en trop dans Frappe héroïque;Astuce : Cri de guerre avant le combat, Exécution sous 20 % de vie"
T["Stats: defense (440 = crit immune vs bosses at 60), stamina, armor, block;Weapon: one-hander + shield, fast weapon = more rage;Rotation: Shield Slam/Revenge, Sunder Armor on the target, Heroic Strike with high rage;Tip: hit helps so Taunt and abilities don't miss"] = "Stats : défense (440 = immunité aux crits des boss au 60), endurance, armure, blocage;Arme : arme à une main + bouclier, arme rapide = plus de rage;Rotation : Heurt de bouclier/Vengeance, Fracasser armure sur la cible, Frappe héroïque avec beaucoup de rage;Astuce : le toucher aide pour que Provocation et les techniques ne ratent pas"
T["Stats: defense, stamina, armor, then spell damage for more threat;Weapon: one-hander (ideally spell damage) + shield;Rotation: Righteous Fury on, Consecration for packs, keep Holy Shield up;Tip: mana is tight - use Seal of Wisdom or some intellect"] = "Stats : défense, endurance, armure, puis dégâts des sorts pour plus de menace;Arme : arme à une main (idéalement dégâts des sorts) + bouclier;Rotation : activer Fureur vertueuse, Consécration pour les groupes, maintenir Bouclier sacré;Astuce : le mana est juste - prendre Sceau de sagesse ou de l'intelligence"
T["Stats: spell damage, spell crit (Elemental Focus saves mana), intellect, mp5;Weapon: one-hander + shield/off-hand with spell damage;Rotation: spam Lightning Bolt, Chain Lightning on packs, Flame Shock;Tip: spell hit up to +16 % in raids, Mana Spring Totem against oom"] = "Stats : dégâts des sorts, critique des sorts (Focalisation élémentaire économise du mana), intelligence, régén. mana;Arme : arme à une main + bouclier/main gauche avec dégâts des sorts;Rotation : spammer Éclair, Chaîne d'éclairs en groupe, Horion de flammes;Astuce : toucher des sorts jusqu'à +16 % en raid, Totem Fontaine de mana contre le mana vide"
T["Stats: spell damage, spell crit, intellect, spell hit up to +16 % in raids;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Moonfire + Insect Swarm, then Wrath or Starfire;Tip: Innervate yourself when mana runs low"] = "Stats : dégâts des sorts, critique des sorts, intelligence, toucher des sorts jusqu'à +16 % en raid;Arme : bâton ou arme à une main + main gauche avec dégâts des sorts;Rotation : Éclat lunaire + Essaim d'insectes, puis Colère ou Feu stellaire;Astuce : Innervation sur vous quand le mana devient juste"
T["Stats: spell damage, spell hit up to +16 % (raid), stamina, intellect;Weapon: staff or dagger + off-hand with spell damage, wand for leftover mana;Rotation: Corruption + curse, then Shadow Bolt; Life Tap instead of drinking;Tip: stamina pays off twice (Life Tap, Voidwalker/Soul Link)"] = "Stats : dégâts des sorts, toucher des sorts jusqu'à +16 % (raid), endurance, intelligence;Arme : bâton ou dague + main gauche avec dégâts des sorts, baguette pour le mana restant;Rotation : Corruption + malédiction, puis Trait de l'ombre ; Connexion au lieu de boire;Astuce : l'endurance compte double (Connexion, Marcheur du Vide/Lien spirituel)"
T["Stats: spell damage, spell hit up to +16 % (raid), spirit for mana;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Shadow Word: Pain, Mind Blast, Mind Flay;Tip: stay in Shadowform, Vampiric Embrace heals the group"] = "Stats : dégâts des sorts, toucher des sorts jusqu'à +16 % (raid), esprit pour le mana;Arme : bâton ou arme à une main + main gauche avec dégâts des sorts;Rotation : Mot de l'ombre : Douleur, Attaque mentale, Fouet mental;Astuce : Forme d'ombre en permanence, Étreinte vampirique soigne le groupe"
T["Stats: spell damage, then spell hit up to +16 % (raid bosses), intellect, spell crit;Weapon: staff with spell damage, plus a wand for leftover mana;Rotation: spam Frostbolt or Fireball, Evocation when out of mana;Leveling: intellect and spirit = less downtime, sheep (moon) in groups"] = "Stats : dégâts des sorts, puis toucher des sorts jusqu'à +16 % (boss de raid), intelligence, critique des sorts;Arme : bâton avec dégâts des sorts, plus une baguette pour le mana restant;Rotation : spammer Éclair de givre ou Boule de feu, Évocation quand le mana est vide;Leveling : intelligence et esprit = moins de pauses, en groupe poser Métamorphose (lune)"
