T["Shows BETTER / WORSE / CAN'T EQUIP with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI is loaded with its own comparison, Oasis shows nothing (avoids doubles) - turn it off there with /nes vergleich."] = "Affiche MIEUX / MOINS BIEN / NON ÉQUIPABLE avec l'effet (DPS, vie, armure) et un tableau de stats. La comparaison Blizzard n'apparaît alors qu'avec Maj. Si nesUI est chargé avec sa propre comparaison, Oasis n'affiche rien (évite les doublons) - désactive-la avec /nes vergleich."
