T["1.  Keep the combat log on (Settings > Areas > Combat board, on by default).\n2.  After playing, double-click ImportCrits.bat in the Oasis folder.\n3.  /reload in game - your highest crit shows here and is shared with the guild."] = "1.  Laisse le journal de combat actif (Options > Sections > Classement de combat, activé par défaut).\n2.  Après avoir joué, double-clique sur ImportCrits.bat dans le dossier Oasis.\n3.  /reload en jeu - ton plus gros critique s'affiche ici et est partagé avec la guilde."
