T["All fonts under the SIL Open Font License 1.1"] = "Toutes les polices sous SIL Open Font License 1.1"
T["All: Burning Adrenaline: run out of the raid AT ONCE (you are about to die).\nAll: Full resources at the start - use everything.\nTank: Set a tank order (Adrenaline on the tank).\nDD: Not in front of or behind the dragon."] = "All: Adrénaline brûlante : sors du raid TOUT DE SUITE (tu vas mourir).\nAll: Ressources pleines au début - lâchez tout.\nTank: Fixer un ordre des tanks (Adrénaline sur le tank).\nDD: Ni devant ni derrière le dragon."
T["All: Do not let the 8 Firesworn die near the raid (explosion).\nTank: Each add tank pulls their Firesworn away, warlocks banish.\nHealer: Dispel, keep an eye on the add tanks.\nDD: Garr first, adds only when called."] = "All: Ne laissez pas les 8 Liges du feu mourir près du raid (explosion).\nTank: Chaque tank d'add éloigne son Lige du feu, les démonistes bannissent.\nHealer: Dissiper, surveiller les tanks d'adds.\nDD: Garr d'abord, les adds seulement sur appel."
T["All: Tank the two Core Ragers away from the boss, do not kill them.\nTank: Swap the Golemagg tank when Magma Splash stacks too high.\nDD: Only on Golemagg."] = "All: Tanker les deux Enragés du Magma loin du boss, ne pas les tuer.\nTank: Changer de tank sur Golemagg quand Eclaboussure de magma monte trop haut.\nDD: Uniquement sur Golemagg."
T["All: The 4 priests first, they heal each other.\nTank: Keep Sulfuron and the priests apart.\nDD: Interrupt! Stop the priests' Dark Mending."] = "All: Les 4 prêtres d'abord, ils se soignent entre eux.\nTank: Séparer Sulfuron et les prêtres.\nDD: Interrompre ! Stopper Dark Mending des prêtres."
T["All: Fire protection! Wrath of Ragnaros knocks melee back - then get back in.\nAll: Sons phase (after 3 min or when he submerges): kill all Sons of Flame.\nTank: Second tank ready when the first is knocked away.\nHealer: Spread out, ranged not too close (Lava Burst).\nDD: Melee: keep mana under control, ranged keep your distance."] = "All: Protection contre le feu ! Colère de Ragnaros projette la mêlée - puis on y retourne.\nAll: Phase des Fils (après 3 min ou quand il s'enfonce) : tuer tous les Fils des flammes.\nTank: Second tank prêt quand le premier est projeté.\nHealer: Dispersés, distance pas trop près (Explosion de lave).\nDD: Mêlée : gérez votre mana, distance : restez à l'écart."
T["All: Flame Buffet stacks - ranged behind pillars to let it drop.\nTank: Two tanks behind pillars, Wing Buffet knocks back.\nDD: Onyxia Scale Cloak required."] = "All: Flame Buffet se cumule - distance derrière les piliers pour le faire tomber.\nTank: Deux tanks derrière les piliers, Frappe des ailes repousse.\nDD: Cape en écailles d'Onyxia obligatoire."
T["All: Remove Gehennas' Curse (reduced healing) at once.\nAll: Get out of the Rain of Fire.\nTank: Tank the two Flamewakers apart.\nDD: Flamewakers first, then Gehennas."] = "All: Retirer la Malédiction de Gehennas (soins réduits) tout de suite.\nAll: Sortez de la Pluie de feu.\nTank: Tanker les deux Attise-flammes séparément.\nDD: Attise-flammes d'abord, puis Gehennas."
T["All: Remove Lucifron's Curse and Impending Doom at once (mages/druids, priests/paladins).\nTank: Tank the two guards apart - mind control!\nHealer: Spread out, dispel mind-controlled players.\nDD: Guards first, then Lucifron."] = "All: Retirer tout de suite la Malédiction de Lucifron et Impending Doom (mages/druides, prêtres/paladins).\nTank: Tanker les deux gardes séparément - contrôle mental !\nHealer: Dispersés, dissiper les joueurs sous contrôle mental.\nDD: Les gardes d'abord, puis Lucifron."
T["All: Living Bomb: run out of the raid AT ONCE!\nAll: Inferno - away from the boss, dispel Ignite Mana.\nTank: Hold the middle, step out briefly on Inferno.\nDD: Melee back off on Inferno."] = "All: Bombe vivante : sors du raid TOUT DE SUITE !\nAll: Inferno - loin du boss, dissiper Enflammer le mana.\nTank: Tenir le centre, sortir brièvement pendant Inferno.\nDD: La mêlée recule pendant Inferno."
T["All: Watch the guards' magic reflection/damage shield - stop damage then.\nTank: One guard per tank, mages sheep the elite guards.\nDD: Healer guards (Flamewaker Healer) first."] = "All: Attention au renvoi de magie/bouclier de dégâts des gardes - stoppez alors les dégâts.\nTank: Un garde par tank, les mages moutonnent les gardes d'élite.\nDD: Les gardes soigneurs (Soigneur attise-flammes) d'abord."
T["All: Never stand in front of or behind Onyxia (breath and tail sweep).\nAll: Phase 2 (65%): dodge fireballs, stay out of the cave entrances.\nAll: Phase 3 (40%): fear - Fear Ward/Tremor Totem ready, avoid the lava cracks.\nTank: Onyxia sideways at the wall, head away from the raid.\nTank: Phase 2: pick up the whelps. Phase 3: get aggro back at once.\nHealer: Tank has priority, spread out in phase 2.\nDD: Wait for 3 attacks of the tank. Phase 2: whelps first."] = "All: Jamais devant ni derrière Onyxia (souffle et balayage de queue).\nAll: Phase 2 (65%): esquiver les boules de feu, pas dans les entrées des grottes.\nAll: Phase 3 (40%): peur - Gardien de peur/Totem de séisme prêts, éviter les fissures de lave.\nTank: Onyxia de côté contre le mur, tête loin du raid.\nTank: Phase 2 : ramasser les dragonnets. Phase 3 : reprendre l'aggro tout de suite.\nHealer: Priorité au tank, dispersés en phase 2.\nDD: Attendre 3 attaques du tank. Phase 2 : dragonnets d'abord."
T["All: Panic - Fear Ward/Tremor Totem, hunters: Tranquilizing Shot on Frenzy.\nAll: Get out of the lava fire on the ground.\nTank: Magmadar with his back to the raid.\nDD: Ranged spread out at the back."] = "All: Panique - Gardien de peur/Totem de séisme, chasseurs : Tir tranquillisant sur Frénésie.\nAll: Sortez du feu de lave au sol.\nTank: Magmadar dos au raid.\nDD: Distance dispersée à l'arrière."
T["All: Phase 1: dragonkin from both sides, watch the class calls.\nAll: Phase 3 (20%): the skeletons rise again - kill them again.\nTank: Nefarian at the wall, fear - Fear Ward.\nHealer: Class call for priests: healing hurts - be careful.\nDD: Hunters/warriors: watch the class calls (weapons gone, stance)."] = "All: Phase 1 : draconides des deux côtés, attention aux appels de classe.\nAll: Phase 3 (20%): les squelettes se relèvent - les tuer à nouveau.\nTank: Nefarian contre le mur, peur - Gardien de peur.\nHealer: Appel de classe prêtres : les soins blessent - attention.\nDD: Chasseurs/guerriers : attention aux appels de classe (armes perdues, posture)."
T["All: Phase 1: destroy the eggs (mind control via the orb), pick up the adds.\nAll: After all eggs: boss in the room - Fire Nova.\nTank: Gather the adds at the stairs.\nDD: Mages and dragonkin first."] = "All: Phase 1 : détruire les œufs (contrôle mental via l'orbe), récupérer les adds.\nAll: Après tous les œufs : boss dans la salle - Nova de feu.\nTank: Regrouper les adds aux escaliers.\nDD: Mages et draconides d'abord."
T["All: Frenzy - hunters: Tranquilizing Shot.\nTank: Two tanks, watch Wing Buffet.\nDD: Onyxia Scale Cloak required."] = "All: Frénésie - chasseurs : Tir tranquillisant.\nTank: Deux tanks, attention à Frappe des ailes.\nDD: Cape en écailles d'Onyxia obligatoire."
T["All: Shadow of Ebonroc heals the boss - the tank with the debuff swaps.\nTank: Two tanks swap on Shadow.\nDD: Onyxia Scale Cloak required."] = "All: Ombre de Rochébène soigne le boss - le tank avec le débuff échange.\nTank: Deux tanks échangent sur Ombre.\nDD: Cape en écailles d'Onyxia obligatoire."
T["All: Knockback - stand against the wall.\nTank: Two tanks, aggro is split by Knock Away.\nDD: Mortal Strike on the tank: healers be prepared."] = "All: Projection - collez-vous au mur.\nTank: Deux tanks, l'aggro est partagée par Repousser au loin.\nDD: Frappe mortelle sur le tank : soigneurs, soyez prêts."
T["All: He teleports - whoever has aggro, do not run away.\nAll: Remove Shazzrah's Curse, Arcane Explosion: melee keep your distance.\nTank: Get back on him right after every blink.\nHealer: Dispel (Deaden Magic)."] = "All: Il se téléporte - celui qui a l'aggro ne s'enfuit pas.\nAll: Retirer la Malédiction de Shazzrah, Explosion des arcanes : mêlée à distance.\nTank: Retourner sur lui juste après chaque transfert.\nHealer: Dissiper (Atténuation de la magie)."
T["All: Two of the five breath types per week - avoid the breath behind the corner.\nAll: Hourglass Sand for the Bronze affliction.\nTank: Tank at the gate, raid behind the corner.\nDD: Tranquilizing Shot on Frenzy."] = "All: Deux des cinq types de souffle par semaine - éviter le souffle derrière l'angle.\nAll: Sable du sablier pour l'affliction de bronze.\nTank: Tanker à la porte, raid derrière l'angle.\nDD: Tir tranquillisant sur Frénésie."
T["Hold Alt: all stats and scoring details. Shift: Blizzard comparison."] = "Maintenir Alt : toutes les stats et le détail du score. Maj : comparaison Blizzard."
T["Release Alt: compact view. Shift: Blizzard comparison."] = "Relâcher Alt : vue compacte. Maj : comparaison Blizzard."
